-- =============================================================
-- 01_create_and_load.sql
-- Mock insurance premium installments (fictional data, no real clients)
-- Loads the RAW export as-is, quirks included, into raw_installments.
-- Run in MySQL Workbench: File > Open SQL Script > Execute (lightning icon)
-- =============================================================

DROP DATABASE IF EXISTS premium_tracker;
CREATE DATABASE premium_tracker;
USE premium_tracker;

CREATE TABLE raw_installments (
    row_id               INT AUTO_INCREMENT PRIMARY KEY,
    insurer              VARCHAR(100),
    customer             VARCHAR(150),
    premium_date         DATE,
    policy_no            VARCHAR(60),
    net_premium          DECIMAL(14,2),
    insurance_type       VARCHAR(20),
    product              VARCHAR(100),
    key_account          VARCHAR(150),   -- Odoo exports an empty value as 'False'
    gross_premium        DECIMAL(14,2),
    effective_from       DATE,
    effective_to         DATE,
    status               VARCHAR(20),
    breakdown_requested  DATE,
    breakdown_received   DATE,
    breakdown_issue      VARCHAR(3),
    breakdown_confirmed  DATE,
    invoice_received     DATE,
    invoice_issue        VARCHAR(3),
    sent_to_client       DATE,
    pop_received         DATE,
    receipt_received     DATE,
    settled_date         DATE
);






-- Check: should return 487
SELECT COUNT(*) AS raw_rows FROM raw_installments;
